(function(){
    if (typeof window === 'undefined') { return; }
    function Editor(options){
        options = options || {};
        this.options = options;
        this.el = options.el;
        if (!this.el) { return; }
        var container = document.createElement('div');
        container.className = 'toastui-editor';
        container.style.height = options.height || '480px';
        container.style.display = 'flex';
        container.style.flexDirection = 'column';

        var textarea = document.createElement('textarea');
        textarea.className = 'toastui-editor-contents';
        textarea.value = options.initialValue || '';
        textarea.setAttribute('aria-label', 'Markdown editor');
        textarea.style.flex = '1 1 auto';
        textarea.style.resize = 'vertical';

        container.appendChild(textarea);
        this.el.innerHTML = '';
        this.el.appendChild(container);

        this._textarea = textarea;
    }
    Editor.prototype.getMarkdown = function(){
        return this._textarea ? this._textarea.value : '';
    };
    Editor.prototype.focus = function(){
        if (this._textarea) { this._textarea.focus(); }
    };

    window.toastui = window.toastui || {};
    window.toastui.Editor = Editor;
})();
